#!/usr/bin/env python3
"""Author the Midterm II reference pages; each source paragraph is original."""
import json,textwrap
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def topic(menu,title,paras):
 lines=[]
 for p in paras:
  lines.extend(textwrap.wrap(p,26,break_long_words=False,break_on_hyphens=False) or [' '])
 pages=[lines[i:i+9] for i in range(0,len(lines),9)]
 return {'menu':menu,'title':title,'pages':pages}
def sec(menu,title,*ts):return {'menu':menu,'title':title,'topics':list(ts)}
def t(m,*paras):return topic(m,m,paras)
enc={'program':'M2ENC','title':'MIDTERM II REFERENCE','sections':[
sec('JOINT LAWS','JOINT DISTRIBUTIONS',
t('PMF AND PDF','PMF p(x,y)=P(X=x,Y=y). All weights nonnegative; sum over every allowed pair =1.','PDF f(x,y)≥0 and integral over support S =1. A density value can exceed1. Point probabilities are0 for joint densities.','If p=cq, c=1/sum(q). If f=cq, c=1/integral(q). Check nonnegativity too.','Freund Ch3 S5 pp82-91. TOOL DISCRETE or DENSITY.'),
t('MARGINALS','pX(x)=sum_y p(x,y). pY(y)=sum_x p(x,y). Keep the named variable; remove the other.','fX(x)=integral f(x,y)dy over allowed y for that x. fY(y)=integral f(x,y)dx over allowed x for that y.','On 0<x<y<1, fX uses y=x..1 and fY uses x=0..y. State support and zero elsewhere.','Freund Ch3 S6 pp92-95.'),
t('CONDITIONAL LAWS','p(X=x|Y=y)=p(x,y)/pY(y). f(X=x|Y=y)=f(x,y)/fY(y) means a density.','The denominator belongs to the GIVEN variable and must be positive. Hold that value fixed; use its support slice.','The conditional sums or integrates to1. For continuous Y, P(Y=y)=0; use densities, not probability division by0.','Joint=conditional*matching marginal. Two marginals alone leave dependence unknown.','Freund Ch3 S7 pp95-101.'),
t('CDF CONVERSIONS','F(x,y)=P(X≤x,Y≤y). Sum masses or integrate density over the lower-left rectangle intersected with support.','f(x,y)=mixed derivative of F for an absolutely continuous law. FX(x)=limit of F(x,y) as y grows.','Rectangle probability = F(b,d) - F(a,d) - F(b,c) + F(a,c).','Integer-inclusive lower endpoints a,c need a-1,c-1. Noninteger supports use left limits.','Give all CDF branches; stop integrating at support edges.'),
t('INDEPENDENCE','Independent iff F(x,y)=FX(x)*FY(y) for every x,y. PMFs factor at every pair. PDFs factor almost everywhere.','Compare the SUPPORT too. Product positive on a region where joint density is0 disproves independence.','Independent => conditional equals marginal; E[g(X)h(Y)]=E[g(X)]E[h(Y)] when integrable.','One agreeing pair never proves independence. Numerical spot checks do not establish a density identity.'),
t('BOUNDS AND WORDS','Draw support S and event A. Integrate on S intersect A. Outer limits are constants; inner limits may depend on outer variable.','X<Y means y>x. X+Y≤b means y≤b-x. Split wherever a boundary changes.','Series device fails if either fails. T=min(X,Y). P(T≤t)=1-P(X>t,Y>t).','Parallel device fails after both fail. T=max(X,Y). P(T≤t)=F(t,t).','Independence is needed to multiply survivals.')),
sec('EXPECT + MOMENTS','EXPECT AND MOMENTS',
t('EXPECTATION','E[X]=sum x*p(x), or integral x*f(x)dx over support. It is a weighted average, not necessarily a possible observed value.','Finite expectation requires E[abs(X)] finite. Symmetry cannot rescue a divergent expectation.','The calculator averages values with weights automatically. Check model and support first.','Freund Ch4 S2 pp113-121.'),
t('LOTUS g(X,Y)','E[g(X)]=sum g(x)p(x), or integral g(x)f(x)dx. No need to derive a transformed distribution first.','For g(X,Y), average g against the JOINT law. A sum of marginal expectations cannot determine general products.','For Y=X², E[Y]=E[X²], E[Y²]=E[X^4]. Var(Y)=E[X^4]-E[X²]².','TOOL FUNCTION g(X,Y) or FUNCTION g(X).'),
t('LINEARITY','E[aX+bY+c]=aE[X]+bE[Y]+c. No independence is required.','E[g(X)] usually differs from g(E[X]). E[X²] usually differs from E[X]².','If X≤Y then E[X]≤E[Y] when expectations exist. E[1_EVENT]=P(EVENT).','A product factors only under suitable independence. Expand polynomial payoffs before taking expectations.'),
t('RAW MOMENTS','Raw rth moment mR=E[X^r]. m0=1; m1=mean; m2=second raw moment.','Use sum x^r*p(x), or integral x^r*f(x)dx. Existing odd moments vanish for symmetry about0.','Mean requires first moment. Variance needs second moment. Variance of X² needs fourth moment.','TOOL PRODUCT MOMENTS with y-power0, or RAW/CENTRAL in DENSITY.'),
t('CENTRAL MOMENTS','Central rth moment=E[(X-M)^r] with M=E[X]. First central moment0. Second central moment=variance.','Var(X)=E[X²]-M² ≥0. SD=sqrt(Var). A zero variance means X constant almost surely.','mu3=m3-3*M*m2+2*M³. mu4 = m4 - 4*M*m3 + 6*M²*m2 - 3*M^4.','Mean has original units; variance has squared units.'),
t('SHIFT SCALE','E[aX+b]=aM+b. Var(aX+b)=a²*Var(X). SD(aX+b)=abs(a)*SD(X).','A shift changes mean but not variance. Negative scaling reverses direction but SD stays nonnegative.','Z=(X-M)/SD has mean0 and variance1 if SD>0. Standardizing alone does not make a law normal.','Freund Ch4 S3 pp121-125.')),
sec('MGFS','MOMENT GENERATING',
t('DEF AND DOMAIN','M(t)=E[e^(tX)]. Discrete sum e^(tx)p(x); continuous integral e^(tx)f(x)dx. The surviving variable is t.','M(0)=1. Standard moment and uniqueness theorems need M finite on an OPEN interval containing0.','For rate L>0 exponential density L*e^(-Lx), M(t)=L/(L-t), t<L.','A numerical finite cutoff cannot prove convergence on an infinite interval.','Freund Ch4 S5 pp127-131.'),
t('MOMENT DERIVS','M^(r)(0)=E[X^r]. Mean=Mprime(0). Second moment=Msecond(0). Variance = Msecond(0) - Mprime(0)².','In a Taylor series multiply coefficient of t^r by r! to obtain the raw moment.','K(t)=ln M(t). Kprime(0)=mean. Ksecond(0)=variance.','Generic numerical MGF tools APPROXIMATE derivatives. Compare two step sizes and keep stable digits; derive exact answers by hand.'),
t('AFFINE AND SUMS','For Z=aX+b, MZ(t)=e^(bt)*MX(at). Change EVERY old t argument to a*t.','For Z=(X-c)/d, MZ(t)=e^(-ct/d)*MX(t/d). d must be nonzero.','The new domain requires a*t in the old domain. Negative a reverses inequalities.','Independent sum => product of MGFs. Weighted sum => product MXi(ai*t), times e^(bt) for offset.'),
t('UNIQUENESS','Equal finite MGFs on a neighborhood of0 imply equal distributions. They do not imply the two variables are independent.','Matching only means and variances does not identify the distribution.','e^(A*t+B*t²) has mean A and variance2B for B≥0. If B<0 it cannot be an MGF near0.','Rate L exponential has mean1/L, second moment2/L², variance1/L².')),
sec('PRODUCT + CORR','PRODUCT MOMENTS',
t('COVARIANCE','Raw product moment E[X^r*Y^s] uses the joint law. Central product moment uses centered factors.','Cov(X,Y)=E[XY]-E[X]E[Y]. Cov(X,X)=Var(X). Cov(X,Y)=Cov(Y,X).','Cov(aX+b,cY+d) = a*c*Cov(X,Y). Added constants vanish. Nonzero covariance disproves independence.','Freund Ch4 S6 pp131-135.'),
t('CORRELATION','rho = Cov(X,Y) / (SD(X)*SD(Y)). Requires positive finite variances. It lies between-1 and1.','abs(Cov)≤SD(X)*SD(Y). An input violating this bound is impossible.','Corr(aX+b,cY+d) = sign(a*c)*rho for nonzero a,c. Positive scale changes leave rho unchanged.','If Y=aX+b, rho=sign(a). Correlation0 means no linear covariance, not absence of dependence.','BT Ch4 S4.5; Freund Ch6 S7.'),
t('ZERO NOT INDEP','Independent with finite moments => Cov0. Converse is false.','Let X uniform(-1,1), Y=X². E[X]=E[X³]=0, so Cov(X,Y)=0.','A=abs(X)<1/2, B=Y<1/4. These events agree. P(A)=P(B)=1/2, P(A and B)=1/2, product=1/4.','Therefore dependent despite correlation0. A deterministic nonconstant square is not independent of its input.')),
sec('LINEAR COMBOS','ONE AND TWO COMBOS',
t('ONE COMBINATION','W=c+sum ai*Xi. Mean=c+sum ai*mean_i.','Var(W)=sum ai²*Var_i +2*sum i<j ai*aj*Cov_ij.','With3 variables include XY,XZ,YZ pairs once each with factor2. Keep signs in cross terms.','Independence OR zero pairwise covariances removes cross terms. Constants add no variance.','Freund Ch4 S7 pp136-138.'),
t('TWO COMBINATIONS','U=sum ai*Xi+c, V=sum bi*Xi+d. Cov(U,V)=sum_i sum_j ai*bj*Cov(Xi,Xj).','For U=aX+bY,V=cX+dY, Cov=ac*VarX+bd*VarY +(ad+bc)*CovXY.','Shared inputs can make combinations dependent even if original variables are independent.','Corr(U,V) = Cov(U,V) / sqrt(VarU*VarV). TOOL LINEAR COMBOS.'),
t('MATRIX SHORTCUT','Put variances on covariance matrix diagonal and covariances symmetrically off diagonal. Call it [A].','Put coefficient rows into [B]. Ignore additive constants for variance/covariance.','[B]*[A]*transpose([B]) gives the output covariance matrix. One row => one variance.','Transpose is MATRIX MATH superscript T token, not alpha T. Manual matrix work is an alternative to the guided app.')),
sec('CONDITION + HELP','CONDITIONING AND HELP',
t('CONDITIONAL MEAN','E[g(X)|Y=y] averages g using conditional weights or density at fixed y.','Equivalent ratio = integral g(x)f(x,y)dx / fY(y). Sum version for a PMF. Denominator must be positive.','Use the conditional slice support. E[X|Y=y]=m(y) is a number; E[X|Y]=m(Y) is a random variable.','TOOL MARG/CONDITIONAL or DENSITY/SLICE with y stored in A.'),
t('CONDITIONAL VAR','Let m=E[X|Y=y] and q=E[X²|Y=y]. Conditional variance=q-m².','Equivalent centered integral E[(X-m)²|Y=y] often avoids subtracting similar numbers.','Independence makes every conditional law equal its marginal. A constant conditional mean by itself does not prove independence.','Freund Ch4 S8 pp138-140.'),
t('TOTAL LAWS','Supplement from BT S4.3. E[X]=E[E[X|Y]].','Var(X)=E[Var(X|Y)] +Var(E[X|Y]).','First term is average within-group spread; second is between-mean spread.','These formulas help recover marginal moments from conditional models. They do not replace the direct normalization step.'),
t('CHOOSE A SOLVER','Finite values => DISCRETE + JOINT. FORMULA/GRID takes x-list,y-list,weight formula. Use y-list{0} for one variable. No need normalize first.','PDF with finite interval or conditional slice => DENSITY + INTEGRAL, 1D.','Joint PDF with explicit inner/outer bounds => DOUBLE INTEGRAL. Split regions at boundary changes.','Given variances/covariances => LINEAR COMBOS. Given MGF => MGF TOOLS. Derivations => ENCYCLOPEDIA.'),
t('INPUT AND LIMITS','Programs use A-Z, theta, strings and custom M2 lists. Existing graph equations and L1-L6 are not edited.','Enter expression tokens normally. X,Y are random-variable arguments; A can hold a fixed parameter in 1D slices.','No symbolic algebra engine. Numerical integration and derivative outputs are approximations.','HOMEWORK MAP then LOAD + SOLVE preloads the given models. Use BACK to exit. ENTER next; LEFT previous; CLEAR menu in reference pages. Check your CE before relying on it.'))
]}
